128	// handleBatchUpsertByPath serves POST /api/v1/services/{serviceName}/...:
129	// the path service name wins even when the body carries its own service_name.
130	func (s *Server) handleBatchUpsertByPath(c *gin.Context) {
131		s.handleBatchUpsert(c, strings.TrimSpace(c.Param("serviceName")), true)
132	}
