140	// handleBatchUpsert registers or overwrites several instances of one service
141	// in one request. Every entry is validated before any write, so an invalid
142	// batch changes no record; the store applies the whole batch atomically.
143	func (s *Server) handleBatchUpsert(c *gin.Context, pathServiceName string, serviceNameFromPath bool) {
144		bag, apiErr := buildParamBag(c)
145		if apiErr != nil {
146			writeError(c, apiErr)
147			return
148		}
149		serviceName := pathServiceName
150		if !serviceNameFromPath {
151			serviceName, apiErr = bag.requiredText(serviceNameKeys, "service_name must not be empty")
152			if apiErr != nil {
153				writeError(c, apiErr)
154				return
155			}
156		} else if serviceName == "" {
157			writeError(c, errInvalidParameter("service_name must not be empty"))
158			return
159		}
160	
161		rawEntries, ok := bag.get([]string{"instances"})
162		if !ok {
163			writeError(c, errInvalidParameter("instances must be a non-empty list"))
164			return
165		}
166		entries, ok := rawEntries.([]any)
167		if !ok || len(entries) == 0 {
168			writeError(c, errInvalidParameter("instances must be a non-empty list"))
169			return
170		}
171	
172		inputs := make([]store.InstanceInput, 0, len(entries))
173		seen := make(map[string]struct{}, len(entries))
174		for _, rawEntry := range entries {
175			entry, ok := rawEntry.(map[string]any)
176			if !ok {
177				writeError(c, errInvalidParameter("each instance must be an object"))
178				return
179			}
180			instanceID := strings.TrimSpace(stringValue(entry["instance_id"]))
181			if instanceID == "" {
182				writeError(c, errInvalidParameter("instance_id must not be empty"))
183				return
184			}
185			if _, duplicated := seen[instanceID]; duplicated {
186				writeError(c, errInvalidParameter("instance_id must not be duplicated"))
187				return
188			}
189			weightValue, present := entry["weight"]
190			if !present {
191				writeError(c, errInvalidParameter("weight must be a positive number"))
192				return
193			}
194			weight, ok := positiveNumber(weightValue)
195			if !ok {
196				writeError(c, errInvalidParameter("weight must be a positive number"))
197				return
198			}
199			port := int64(0)
200			if portValue, present := entry["port"]; present {
201				port, ok = parsePortValue(portValue)
202				if !ok {
203					writeError(c, errInvalidParameter("port must be a non-negative integer"))
204					return
205				}
206			}
207			healthy := false
208			if healthValue, present := entry["healthy"]; present {
209				healthy, ok = strictBoolValue(healthValue)
210				if !ok {
211					writeError(c, errInvalidParameter("healthy must be a boolean true or false"))
212					return
213				}
214			}
215			heartbeatValue, present := entry["heartbeat_at"]
216			if !present {
217				writeError(c, errInvalidParameter("heartbeat_at is required"))
218				return
219			}
220			heartbeatAt, parsed := parseTimeValue(heartbeatValue)
221			if !parsed {
222				writeError(c, errInvalidParameter("heartbeat_at must be a valid timestamp"))
223				return
224			}
225			address := ""
226			if addressValue, present := entry["address"]; present {
227				address = stringValue(addressValue)
228			}
229			seen[instanceID] = struct{}{}
230			inputs = append(inputs, store.InstanceInput{
231				ServiceName: serviceName,
232				InstanceID:  instanceID,
233				Address:     address,
234				Port:        port,
235				Healthy:     healthy,
236				Weight:      weight,
237				HeartbeatAt: heartbeatAt,
238			})
239		}
240	
241		instances, err := s.store.UpsertInstances(inputs)
242		if err != nil {
243			writeError(c, errStorageUnavailable())
244			return
245		}
246		results := make([]gin.H, 0, len(instances))
247		for _, instance := range instances {
248			results = append(results, instanceJSON(instance))
249		}
250		c.JSON(200, gin.H{
251			"service_name": serviceName,
252			"registered":   len(results),
253			"instances":    results,
254		})
255	}
