285	// handleHeartbeat renews heartbeat_at of one path-addressed instance. The
286	// caller does not resubmit address, port, health state or weight: only
287	// heartbeat_at is replaced and every other field keeps its current value.
288	func (s *Server) handleHeartbeat(c *gin.Context) {
289		bag, apiErr := buildParamBag(c)
290		if apiErr != nil {
291			writeError(c, apiErr)
292			return
293		}
294		serviceName, apiErr := bag.locateText("serviceName", serviceNameKeys, "service_name must not be empty")
295		if apiErr != nil {
296			writeError(c, apiErr)
297			return
298		}
299		instanceID, apiErr := bag.locateText("instanceId", instanceIDKeys, "instance_id must not be empty")
300		if apiErr != nil {
301			writeError(c, apiErr)
302			return
303		}
304		heartbeatAt, apiErr := requireHeartbeat(bag)
305		if apiErr != nil {
306			writeError(c, apiErr)
307			return
308		}
309		updated, err := s.store.TouchHeartbeats(serviceName, []store.HeartbeatTarget{
310			{InstanceID: instanceID, HeartbeatAt: heartbeatAt},
311		})
312		if apiErr := mapTargetError(err); apiErr != nil {
313			writeError(c, apiErr)
314			return
315		}
316		c.JSON(200, gin.H{"instance": instanceJSON(updated[0])})
317	}
