388	func requireHeartbeat(bag *paramBag) (time.Time, *apiError) {
389		heartbeatValue, ok := bag.get(heartbeatKeys)
390		if !ok {
391			return time.Time{}, errInvalidParameter("heartbeat_at is required")
392		}
393		heartbeatAt, ok := parseTimeValue(heartbeatValue)
394		if !ok {
395			return time.Time{}, errInvalidParameter("heartbeat_at must be a valid timestamp")
396		}
397		return heartbeatAt, nil
398	}
