514	func mapTargetError(err error) *apiError {
515		switch {
516		case err == nil:
517			return nil
518		case errors.Is(err, store.ErrInstanceNotFound):
519			return errInstanceNotFound()
520		default:
521			return errStorageUnavailable()
522		}
523	}
