643		instance, found, err := s.store.GetInstance(serviceName, instanceID)
644		if err != nil {
645			return store.Instance{}, errStorageUnavailable()
646		}
647		if !found {
648			return store.Instance{}, errInstanceNotFound()
649		}
650		return instance, nil
651	}
652	
