129	// readJSONObject requires the request body to be a single JSON object. An
130	// empty body, a JSON array or any non-object payload is a parameter error.
131	// It is used by the batch entry points whose contract forbids merging query
132	// parameters or accepting a bare value.
133	func readJSONObject(c *gin.Context) (map[string]any, *apiError) {
134		if c.Request.Body == nil {
135			return nil, errInvalidParameter("request body must be a JSON object")
136		}
137		raw, err := io.ReadAll(c.Request.Body)
