158	// readHealthyInput accepts a new healthy state for one instance from either a
159	// JSON body field ("healthy": true|false) or the ?healthy=true|false query
160	// parameter. The JSON field wins when both carry it. JSON accepts only
161	// booleans, while the query parameter accepts only the lowercase text "true"
162	// or "false"; every other representation is a parameter error.
163	func readHealthyInput(c *gin.Context) (bool, *apiError) {
164		queryValue, queryPresent := c.GetQuery("healthy")
165	
166		if c.Request.Body != nil {
167			raw, err := io.ReadAll(c.Request.Body)
168			if err != nil {
169				return false, errInvalidParameter("request body cannot be read")
170			}
171			if len(bytes.TrimSpace(raw)) > 0 {
172				var body map[string]any
173				if err := json.Unmarshal(raw, &body); err != nil || body == nil {
174					return false, errInvalidParameter("request body must be a JSON object")
175				}
