23	func TestBatchRegisterByPathRegistersInOrder(t *testing.T) {
24		router, st := testRouter(t)
25		body := map[string]any{
26			// Even if the body carries a service name, the path value wins.
27			"service_name": "ignored",
28			"instances": []any{
29				batchEntry("i-2"),
30				batchEntry("i-1"),
31			},
32		}
33		rec := doRequest(t, router, http.MethodPost,
34			"/api/v1/services/billing/instances/batch", body)
35		if rec.Code != http.StatusOK {
36			t.Fatalf("status = %d body %s", rec.Code, rec.Body.String())
37		}
38		out := decodeBody(t, rec)
39		if out["service_name"] != "billing" {
40			t.Fatalf("service_name = %v, want billing", out["service_name"])
41		}
42		if out["registered"].(float64) != 2 {
43			t.Fatalf("registered = %v, want 2", out["registered"])
44		}
45		entries := out["instances"].([]any)
46		if len(entries) != 2 {
47			t.Fatalf("instances len = %d", len(entries))
48		}
49		if entries[0].(map[string]any)["instance_id"] != "i-2" ||
50			entries[1].(map[string]any)["instance_id"] != "i-1" {
51			t.Fatalf("order not preserved")
52		}
53		for _, id := range []string{"i-1", "i-2"} {
54			got, found, err := st.GetInstance("billing", id)
55			if err != nil || !found {
56				t.Fatalf("%s: found=%v err=%v", id, found, err)
57			}
58			if got.ServiceName != "billing" {
59				t.Fatalf("%s stored under %q", id, got.ServiceName)
60			}
61		}
62		if _, found, _ := st.GetInstance("ignored", "i-1"); found {
63			t.Fatalf("body service name must be ignored on the path entry")
64		}
65	}
66	
67	func TestBatchRegisterByBodyAndOverwrite(t *testing.T) {
68		router, st := testRouter(t)
