		t.Fatalf("instances is not a list: %v", out)
	}
	ids := make([]string, 0, len(rawList))
	for _, raw := range rawList {
		item := raw.(map[string]any)
		ids = append(ids, item["instance_id"].(string))
	}
	return ids
}

